const blockTypes = [['hero', 'Hero'], ['heading', 'Heading'], ['paragraph', 'Paragraph'], ['rich_text', 'Rich text'], ['image', 'Image'], ['banner', 'Banner'], ['button_group', 'Buttons'], ['feature_cards', 'Feature cards'], ['trust_badges', 'Trust badges'], ['category_grid', 'Categories'], ['brand_grid', 'Brands'], ['industry_grid', 'Industries'], ['product_grid', 'Products'], ['row', 'Columns'], ['spacer', 'Spacer'], ['divider', 'Divider']]
const uid = (prefix = 'block') => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
const deepClone = (value) => JSON.parse(JSON.stringify(value))
const makeBlock = (type) => ({ id: uid(type), type, visible: true, settings: ({
  hero: { eyebrow: 'Marketplace', title: 'Build your next success story.', description: 'Add a clear value proposition for your customers.', search_placeholder: 'Search solutions', background_media_id: null, trust_points: ['Verified vendors', 'Transparent pricing'], alignment: 'left' },
  heading: { eyebrow: 'Explore', title: 'A new marketplace section', alignment: 'left' }, paragraph: { text: 'Add your content here.', alignment: 'left' }, rich_text: { content: [{ type: 'paragraph', text: 'Add structured content here.' }], alignment: 'left' }, image: { media_id: null, caption: '', alignment: 'center' }, banner: { title: 'Ready to get started?', description: 'Connect with the right solution provider.', button_label: 'Explore now', target: '/marketplace', background_media_id: null, alignment: 'left' }, button_group: { items: [{ id: uid('button'), label: 'Explore', target: '/marketplace' }], alignment: 'center' }, feature_cards: { items: [{ id: uid('card'), title: 'Feature', description: 'Explain this benefit.' }] }, trust_badges: { items: [{ id: uid('badge'), title: 'Trusted', description: 'Verified marketplace partners.' }] }, category_grid: { eyebrow: 'Categories', title: 'Browse categories', catalog_ids: [], columns: 4 }, brand_grid: { title: 'Featured brands', display: 'grid', catalog_ids: [] }, industry_grid: { eyebrow: 'Industries', title: 'Browse industries', catalog_ids: [], columns: 4 }, product_grid: { eyebrow: 'Marketplace', title: 'Featured solutions', description: 'Explore selected solutions.', catalog_ids: [], show_filters: true, columns: 3 }, row: { columns: 2, children: [] }, spacer: { height: 32 }, divider: {},
}[type] || {}) })

function normalizeDocument(value) {
  const document = deepClone(value)
  document.theme = { muted: '#64748B', section_spacing: 'comfortable', ...document.theme }
  document.seo = { title: '', description: '', share_media_id: null, ...document.seo }
  document.header = { login_label: 'Log In', signup_label: 'Sign Up', ...document.header }
  const walk = (blocks) => blocks.map((block) => block.type === 'rich_text' && !block.settings.content ? { ...block, settings: { ...block.settings, content: (block.settings.text || '').split('\n').filter(Boolean).map((text) => ({ type: 'paragraph', text })) } } : { ...block, settings: block.settings?.children ? { ...block.settings, children: walk(block.settings.children) } : block.settings })
  document.sections = walk(document.sections || [])
  document.sections = document.sections.map((block) => block.type === 'hero' ? { ...block, settings: { featured_ads: [], ...block.settings } } : block)
  return document
}
function findBlock(blocks, id) { for (const block of blocks) { if (block.id === id) return block; const found = findBlock(block.settings?.children || [], id); if (found) return found } return null }
const mapBlocks = (blocks, id, mutate) => blocks.map((block) => block.id === id ? mutate(block) : ({ ...block, settings: block.settings?.children ? { ...block.settings, children: mapBlocks(block.settings.children, id, mutate) } : block.settings }))
const removeBlock = (blocks, id) => blocks.filter((block) => block.id !== id).map((block) => ({ ...block, settings: block.settings?.children ? { ...block.settings, children: removeBlock(block.settings.children, id) } : block.settings }))
function reidentify(block) { const copy = deepClone(block); const walk = (item) => ({ ...item, id: uid(item.type), settings: { ...item.settings, items: item.settings?.items?.map((entry) => ({ ...entry, id: uid('item') })), children: item.settings?.children?.map(walk) } }); return walk(copy) }
function moveSibling(blocks, id, direction) {
  const index = blocks.findIndex((block) => block.id === id)
  if (index >= 0) { const target = index + direction; if (target < 0 || target >= blocks.length) return blocks; const next = [...blocks]; [next[index], next[target]] = [next[target], next[index]]; return next }
  return blocks.map((block) => ({ ...block, settings: block.settings?.children ? { ...block.settings, children: moveSibling(block.settings.children, id, direction) } : block.settings }))
}
function insertBlock(blocks, targetId, block, inside) {
  if (inside) return mapBlocks(blocks, targetId, (target) => ({ ...target, settings: { ...target.settings, children: [...(target.settings.children || []), block] } }))
  const index = blocks.findIndex((item) => item.id === targetId)
  if (index >= 0) { const next = [...blocks]; next.splice(index, 0, block); return next }
  return blocks.map((item) => ({ ...item, settings: item.settings?.children ? { ...item.settings, children: insertBlock(item.settings.children, targetId, block, false) } : item.settings }))
}

function TextField({ label, value = '', onChange, multiline = false, type = 'text', maxLength }) { const Tag = multiline ? 'textarea' : 'input'; return <label className="block text-xs font-semibold text-slate-700 dark:text-slate-200">{label}<Tag type={type} rows={multiline ? 4 : undefined} maxLength={maxLength} value={value ?? ''} onChange={(event) => onChange(event.target.value)} className="mt-1.5 w-full rounded-lg border bg-white px-3 py-2 text-sm font-normal outline-none focus:border-primary dark:bg-slate-900"/>{maxLength && <span className="mt-1 block text-right text-[11px] font-normal text-slate-400">{String(value || '').length}/{maxLength}</span>}</label> }
function SelectField({ label, value, onChange, options }) { return <label className="block text-xs font-semibold text-slate-700 dark:text-slate-200">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="mt-1.5 h-10 w-full rounded-lg border bg-white px-3 text-xs font-normal dark:bg-slate-900">{options.map(([key, text]) => <option key={key} value={key}>{text}</option>)}</select></label> }
function MediaPicker({ label, value, media, onChange }) { return <label className="block text-xs font-semibold text-slate-700 dark:text-slate-200">{label}<select value={value || ''} onChange={(event) => onChange(event.target.value ? Number(event.target.value) : null)} className="mt-1.5 h-10 w-full rounded-lg border bg-white px-3 text-xs font-normal dark:bg-slate-900"><option value="">No image</option>{media.map((asset) => <option key={asset.id} value={asset.id}>{asset.original_name} — {asset.alt_text}</option>)}</select></label> }

function HeaderLogoPicker({ value, media, onChange, onUploaded, canUpload }) {
  const inputRef = useRef(null); const [uploading, setUploading] = useState(false); const [error, setError] = useState('')
  const selectedAsset = media.find((asset) => Number(asset.id) === Number(value))
  const upload = async (event) => {
    const file = event.target.files?.[0]; event.target.value = ''; if (!file) return
    const data = new FormData(); data.append('file', file); data.append('alt_text', `Header logo for ${file.name.replace(/\.[^.]+$/, '')}`)
    setUploading(true); setError('')
    try { const result = await uploadMarketplaceMedia(data); onUploaded(result.data); onChange(Number(result.data.id)) } catch (requestError) { setError(requestError.message) } finally { setUploading(false) }
  }
  return <div><p className="text-xs font-semibold text-slate-700 dark:text-slate-200">Logo</p>{selectedAsset && <div className="mt-1.5 flex items-center gap-3 rounded-lg border bg-slate-50 p-3 dark:bg-slate-950"><img src={selectedAsset.url} alt={selectedAsset.alt_text} className="h-12 w-16 rounded bg-white object-contain p-1"/><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{selectedAsset.original_name}</p><p className="mt-0.5 text-[11px] text-slate-500">{selectedAsset.width}×{selectedAsset.height}px</p></div></div>}<select value={value || ''} onChange={(event) => onChange(event.target.value ? Number(event.target.value) : null)} className="mt-2 h-10 w-full rounded-lg border bg-white px-3 text-xs font-normal dark:bg-slate-900"><option value="">Use default logo</option>{media.map((asset) => <option key={asset.id} value={asset.id}>{asset.original_name} — {asset.alt_text}</option>)}</select><div className="mt-2 flex gap-2">{canUpload && <><input ref={inputRef} type="file" accept="image/png,image/jpeg,image/webp" onChange={upload} className="hidden"/><button type="button" disabled={uploading} onClick={() => inputRef.current?.click()} className="flex-1 rounded-lg border border-primary px-3 py-2 text-xs font-semibold text-primary hover:bg-blue-50 disabled:opacity-50">{uploading ? 'Uploading…' : selectedAsset ? 'Change logo' : 'Upload new logo'}</button></>}{value && <button type="button" onClick={() => onChange(null)} className="rounded-lg border px-3 py-2 text-xs font-semibold text-red-600 hover:bg-red-50">Remove</button>}</div><p className="mt-1.5 text-[11px] text-slate-400">PNG, JPG or WebP · maximum 8 MB</p>{error && <p role="alert" className="mt-1.5 text-xs text-red-600">{error}</p>}</div>
}

function CatalogPicker({ type, value = [], catalog, onChange }) {
  const [search, setSearch] = useState(''); const rows = catalog[type] || []; const selected = new Set(value.map(Number)); const rowMap = new Map(rows.map((item) => [Number(item.id), item])); const filtered = rows.filter((row) => `${row.name} ${row.vendor || ''}`.toLowerCase().includes(search.toLowerCase())).slice(0, 100)
  const toggle = (id) => onChange(selected.has(Number(id)) ? value.filter((item) => Number(item) !== Number(id)) : [...value, Number(id)])
  const move = (index, direction) => { const target = index + direction; if (target < 0 || target >= value.length) return; const next = [...value]; [next[index], next[target]] = [next[target], next[index]]; onChange(next) }
  return <div><p className="text-xs font-semibold">Selected {type} ({value.length})</p><div className="mt-2 max-h-44 space-y-1 overflow-y-auto rounded-lg border p-2">{value.map((id, index) => <div key={id} className="flex items-center gap-2 rounded bg-blue-50 px-2 py-1.5 text-xs dark:bg-blue-950/30"><span className="min-w-0 flex-1 truncate">{rowMap.get(Number(id))?.name || `#${id}`}</span><button type="button" onClick={() => move(index, -1)} aria-label="Move up"><ChevronUp className="h-3.5 w-3.5"/></button><button type="button" onClick={() => move(index, 1)} aria-label="Move down"><ChevronDown className="h-3.5 w-3.5"/></button><button type="button" onClick={() => toggle(id)} aria-label="Remove"><Trash2 className="h-3.5 w-3.5 text-red-500"/></button></div>)}{!value.length && <p className="py-3 text-center text-xs text-slate-400">No records selected.</p>}</div><details className="mt-2 rounded-lg border"><summary className="cursor-pointer px-3 py-2 text-xs font-semibold">Add records</summary><div className="border-t p-2"><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={`Search ${type}`} className="mb-2 h-9 w-full rounded-lg border px-3 text-xs"/><div className="max-h-52 overflow-y-auto">{filtered.map((row) => <label key={row.id} className="flex min-h-9 items-center gap-2 rounded px-2 text-xs hover:bg-slate-50 dark:hover:bg-slate-800"><input type="checkbox" checked={selected.has(Number(row.id))} onChange={() => toggle(row.id)}/><span className="truncate">{row.name}{row.vendor ? ` — ${row.vendor}` : ''}</span></label>)}</div></div></details></div>
}

export function FeaturedAdsEditor({ value = [], catalog, onChange }) {
  const services = catalog.services || []; const selected = new Set(value.map((ad) => Number(ad.service_id)))
  const add = (event) => { const serviceId = Number(event.target.value); if (!serviceId || selected.has(serviceId)) return; onChange([...value, { service_id: serviceId, duration_seconds: 6 }]); event.target.value = '' }
  const update = (index, patch) => onChange(value.map((ad, adIndex) => adIndex === index ? { ...ad, ...patch } : ad)); const move = (index, direction) => { const target = index + direction; if (target < 0 || target >= value.length) return; const next = [...value]; [next[index], next[target]] = [next[target], next[index]]; onChange(next) }
  return <div className="rounded-xl border bg-blue-50/40 p-3 dark:bg-blue-950/20"><p className="text-xs font-bold text-primary">Featured Ads</p><p className="mt-1 text-[11px] leading-4 text-slate-500">Add multiple software ads and set how many seconds each remains visible.</p><select defaultValue="" onChange={add} className="mt-3 h-10 w-full rounded-lg border bg-white px-3 text-xs dark:bg-slate-900"><option value="">+ Add software</option>{services.filter((service) => !selected.has(Number(service.id))).map((service) => <option key={service.id} value={service.id}>{service.name} — {service.vendor || 'Vendor'}</option>)}</select><div className="mt-3 space-y-2">{value.map((ad, index) => { const service = services.find((row) => Number(row.id) === Number(ad.service_id)); return <div key={`${ad.service_id}-${index}`} className="rounded-lg border bg-white p-2.5 dark:bg-slate-900"><div className="flex items-center gap-2"><span className="min-w-0 flex-1 truncate text-xs font-semibold">{service?.name || `Software #${ad.service_id}`}</span><button type="button" onClick={() => move(index, -1)} aria-label="Move ad up"><ChevronUp className="h-4 w-4"/></button><button type="button" onClick={() => move(index, 1)} aria-label="Move ad down"><ChevronDown className="h-4 w-4"/></button><button type="button" onClick={() => onChange(value.filter((_, adIndex) => adIndex !== index))} aria-label="Remove ad"><Trash2 className="h-4 w-4 text-red-500"/></button></div><label className="mt-2 flex items-center gap-2 text-[11px] font-semibold text-slate-500">Display duration<input type="number" min="2" max="120" value={ad.duration_seconds || 6} onChange={(event) => update(index, { duration_seconds: Math.min(120, Math.max(2, Number(event.target.value) || 2)) })} className="h-8 w-20 rounded-lg border px-2 text-xs text-slate-900"/>seconds</label></div>})}{!value.length && <p className="rounded-lg border border-dashed p-3 text-center text-[11px] text-slate-400">No featured ads selected.</p>}</div></div>
}

function ItemList({ title, items = [], onChange, fields = ['title', 'description'], extra }) {
  const update = (index, key, value) => onChange(items.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item))
  const move = (index, direction) => { const target = index + direction; if (target < 0 || target >= items.length) return; const next = [...items]; [next[index], next[target]] = [next[target], next[index]]; onChange(next) }
  return <div><div className="flex items-center justify-between"><p className="text-xs font-semibold">{title}</p><button type="button" onClick={() => onChange([...items, { id: uid('item'), ...Object.fromEntries(fields.map((field) => [field, ''])), ...(extra || {}) }])} className="text-xs font-semibold text-primary">+ Add</button></div><div className="mt-2 space-y-3">{items.map((item, index) => <div key={item.id} className="space-y-2 rounded-lg border p-3"><div className="flex justify-end gap-2"><button type="button" onClick={() => move(index, -1)} aria-label="Move item up"><ChevronUp className="h-4 w-4"/></button><button type="button" onClick={() => move(index, 1)} aria-label="Move item down"><ChevronDown className="h-4 w-4"/></button></div>{fields.map((field) => <TextField key={field} label={field.replaceAll('_', ' ')} value={item[field]} onChange={(value) => update(index, field, value)}/>)}{extra?.kind && <SelectField label="Platform" value={item.kind || 'x'} onChange={(value) => update(index, 'kind', value)} options={['x', 'linkedin', 'facebook', 'youtube'].map((key) => [key, key === 'x' ? 'X' : key[0].toUpperCase() + key.slice(1)])}/>}<button type="button" onClick={() => onChange(items.filter((_, itemIndex) => itemIndex !== index))} className="text-xs font-semibold text-red-600">Remove item</button></div>)}</div></div>
}

function RichTextEditor({ value = [], onChange }) {
  const update = (index, patch) => onChange(value.map((node, nodeIndex) => nodeIndex === index ? { ...node, ...patch } : node))
  return <div><div className="flex items-center justify-between"><p className="text-xs font-semibold">Structured content</p><button type="button" onClick={() => onChange([...value, { type: 'paragraph', text: '' }])} className="text-xs font-semibold text-primary">+ Add node</button></div><div className="mt-2 space-y-2">{value.map((node, index) => <div key={index} className="rounded-lg border p-2"><SelectField label="Style" value={node.type} onChange={(type) => update(index, { type })} options={[["paragraph", "Paragraph"], ["heading", "Heading"], ["bullet", "Bullet"]]}/><textarea rows="3" value={node.text} onChange={(event) => update(index, { text: event.target.value })} className="mt-2 w-full rounded-lg border p-2 text-sm"/><button type="button" onClick={() => onChange(value.filter((_, nodeIndex) => nodeIndex !== index))} className="text-xs font-semibold text-red-600">Remove</button></div>)}</div></div>
}

function FooterColumns({ columns = [], onChange }) {
  const update = (index, patch) => onChange(columns.map((column, columnIndex) => columnIndex === index ? { ...column, ...patch } : column))
  return <div><div className="flex items-center justify-between"><p className="text-xs font-semibold">Footer columns</p><button type="button" onClick={() => onChange([...columns, { id: uid('column'), title: 'New column', links: [] }])} className="text-xs font-semibold text-primary">+ Add column</button></div><div className="mt-2 space-y-3">{columns.map((column, index) => <div key={column.id} className="rounded-lg border p-3"><TextField label="Column title" value={column.title} onChange={(title) => update(index, { title })}/><ItemList title="Links" items={column.links || []} fields={['label', 'target']} onChange={(links) => update(index, { links })}/><button type="button" onClick={() => onChange(columns.filter((_, columnIndex) => columnIndex !== index))} className="mt-2 text-xs font-semibold text-red-600">Remove column</button></div>)}</div></div>
}

function BlockInspector({ block, update, media, catalog }) {
  if (!block) return <EmptyState title="Select a block" description="Choose a block from the section tree to edit it."/>
  const set = (key, value) => update({ ...block, settings: { ...block.settings, [key]: value } }); const s = block.settings || {}; const catalogType = { category_grid: 'categories', brand_grid: 'brands', industry_grid: 'industries', product_grid: 'services' }[block.type]
  return <div className="space-y-4"><div><Badge tone="primary">{block.type.replaceAll('_', ' ')}</Badge><label className="mt-3 flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={block.visible !== false} onChange={(event) => update({ ...block, visible: event.target.checked })}/>Visible on marketplace</label></div>{'eyebrow' in s && <TextField label="Eyebrow" value={s.eyebrow} onChange={(value) => set('eyebrow', value)}/>} {'title' in s && <TextField label="Title" value={s.title} onChange={(value) => set('title', value)}/>} {'description' in s && <TextField label="Description" value={s.description} multiline onChange={(value) => set('description', value)}/>} {'text' in s && block.type !== 'rich_text' && <TextField label="Content" value={s.text} multiline onChange={(value) => set('text', value)}/>} {block.type === 'rich_text' && <RichTextEditor value={s.content || []} onChange={(value) => set('content', value)}/>} {'caption' in s && <TextField label="Caption" value={s.caption} onChange={(value) => set('caption', value)}/>} {'search_placeholder' in s && <TextField label="Search placeholder" value={s.search_placeholder} onChange={(value) => set('search_placeholder', value)}/>} {'button_label' in s && <TextField label="Button label" value={s.button_label} onChange={(value) => set('button_label', value)}/>} {'target' in s && <TextField label="Button destination" value={s.target} onChange={(value) => set('target', value)}/>} {'media_id' in s && <MediaPicker label="Image" value={s.media_id} media={media} onChange={(value) => set('media_id', value)}/>} {'background_media_id' in s && <MediaPicker label="Background image" value={s.background_media_id} media={media} onChange={(value) => set('background_media_id', value)}/>} {Array.isArray(s.trust_points) && <TextField label="Trust points (one per line)" value={s.trust_points.join('\n')} multiline onChange={(value) => set('trust_points', value.split('\n').filter(Boolean))}/>} {catalogType && <CatalogPicker type={catalogType} value={s.catalog_ids} catalog={catalog} onChange={(value) => set('catalog_ids', value)}/>} {'columns' in s && <SelectField label="Columns" value={s.columns} onChange={(value) => set('columns', Number(value))} options={[[1, '1 column'], [2, '2 columns'], [3, '3 columns'], [4, '4 columns']]}/>} {'display' in s && <SelectField label="Display" value={s.display} onChange={(value) => set('display', value)} options={[["grid", "Grid"], ["marquee", "Marquee"]]}/>} {'show_filters' in s && <label className="flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={s.show_filters} onChange={(event) => set('show_filters', event.target.checked)}/>Show product filters</label>} {'height' in s && <TextField type="number" label="Height in pixels" value={s.height} onChange={(value) => set('height', Number(value))}/>} {Array.isArray(s.items) && <ItemList title="Items" items={s.items} fields={block.type === 'button_group' ? ['label', 'target'] : ['title', 'description']} onChange={(value) => set('items', value)}/>}<hr/><p className="text-xs font-semibold">Section appearance</p><SelectField label="Alignment" value={s.alignment || 'left'} onChange={(value) => set('alignment', value)} options={[["left", "Left"], ["center", "Center"], ["right", "Right"]]}/><TextField type="number" label="Top spacing (0–160px)" value={s.padding_top ?? ''} onChange={(value) => set('padding_top', value === '' ? undefined : Number(value))}/><TextField type="number" label="Bottom spacing (0–160px)" value={s.padding_bottom ?? ''} onChange={(value) => set('padding_bottom', value === '' ? undefined : Number(value))}/><label className="flex items-center justify-between text-xs font-semibold">Background<input type="color" value={s.background_color || '#ffffff'} onChange={(event) => set('background_color', event.target.value)} className="h-10 w-16 rounded border"/></label></div>
}

function ShellInspector({ target, document, updateDocument, media, onMediaUploaded, canUploadMedia }) {
  if (target === 'theme') { const theme = document.theme; const set = (key, value) => updateDocument({ ...document, theme: { ...theme, [key]: value } }); return <div className="space-y-4">{['primary', 'secondary', 'canvas', 'surface', 'text', 'muted'].map((key) => <label key={key} className="flex items-center justify-between gap-3 text-xs font-semibold capitalize">{key}<input type="color" value={theme[key]} onChange={(event) => set(key, event.target.value)} className="h-10 w-16 rounded border"/></label>)}<SelectField label="Font" value={theme.font} onChange={(value) => set('font', value)} options={[["Inter", "Inter"], ["System", "System"]]}/><SelectField label="Radius" value={theme.radius} onChange={(value) => set('radius', value)} options={[["square", "Square"], ["soft", "Soft"], ["rounded", "Rounded"]]}/><SelectField label="Container" value={theme.container} onChange={(value) => set('container', value)} options={[["compact", "Compact"], ["wide", "Wide"], ["full", "Full"]]}/><SelectField label="Section spacing" value={theme.section_spacing} onChange={(value) => set('section_spacing', value)} options={[["compact", "Compact"], ["comfortable", "Comfortable"], ["spacious", "Spacious"]]}/></div> }
  if (target === 'seo') { const seo = document.seo || {}; const set = (key, value) => updateDocument({ ...document, seo: { ...seo, [key]: value } }); return <div className="space-y-4"><TextField label="SEO title" maxLength={70} value={seo.title} onChange={(value) => set('title', value)}/><TextField label="Meta description" maxLength={170} multiline value={seo.description} onChange={(value) => set('description', value)}/><MediaPicker label="Social share image" value={seo.share_media_id} media={media} onChange={(value) => set('share_media_id', value)}/></div> }
  if (target === 'header') { const header = document.header; const set = (key, value) => updateDocument({ ...document, header: { ...header, [key]: value } }); return <div className="space-y-4"><TextField label="Brand name" value={header.brand_name} onChange={(value) => set('brand_name', value)}/><TextField label="Tagline" value={header.tagline} onChange={(value) => set('tagline', value)}/><HeaderLogoPicker value={header.logo_media_id} media={media} onChange={(value) => set('logo_media_id', value)} onUploaded={onMediaUploaded} canUpload={canUploadMedia}/><TextField label="Login label" value={header.login_label} onChange={(value) => set('login_label', value)}/><TextField label="Signup label" value={header.signup_label} onChange={(value) => set('signup_label', value)}/><ItemList title="Navigation" items={header.nav || []} fields={['label', 'target']} onChange={(items) => set('nav', items.map((item) => ({ ...item, kind: ['categories', 'brands', 'industries'].includes(item.target) ? 'catalog' : item.target?.startsWith('/') ? 'internal' : 'external' })))}/><TextField label="CTA label" value={header.cta?.label} onChange={(value) => set('cta', { ...header.cta, label: value })}/><TextField label="CTA destination" value={header.cta?.target} onChange={(value) => set('cta', { ...header.cta, target: value })}/></div> }
  const footer = document.footer; const set = (key, value) => updateDocument({ ...document, footer: { ...footer, [key]: value } }); return <div className="space-y-4"><TextField label="Footer description" value={footer.description} multiline onChange={(value) => set('description', value)}/><TextField label="Copyright" value={footer.copyright} onChange={(value) => set('copyright', value)}/><ItemList title="Social links" items={footer.socials} fields={['label', 'target']} extra={{ kind: 'x' }} onChange={(value) => set('socials', value)}/><FooterColumns columns={footer.columns} onChange={(value) => set('columns', value)}/><label className="flex items-center gap-2 text-xs font-semibold"><input type="checkbox" checked={footer.newsletter?.visible !== false} onChange={(event) => set('newsletter', { ...footer.newsletter, visible: event.target.checked })}/>Show newsletter</label><TextField label="Newsletter title" value={footer.newsletter?.title} onChange={(value) => set('newsletter', { ...footer.newsletter, title: value })}/><TextField label="Newsletter description" value={footer.newsletter?.description} multiline onChange={(value) => set('newsletter', { ...footer.newsletter, description: value })}/><TextField label="Newsletter button" value={footer.newsletter?.button_label} onChange={(value) => set('newsletter', { ...footer.newsletter, button_label: value })}/></div>
}

function TreeNode({ block, depth, selected, setSelected, add, move, duplicate, remove, dragId, drop }) {
  const children = block.settings?.children || []
  return <div role="treeitem" aria-selected={selected === block.id} className="space-y-2" style={{ marginLeft: depth ? 16 : 0 }}><article draggable onDragStart={() => { dragId.current = block.id }} onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.stopPropagation(); drop(block.id, block.type === 'row') }} onClick={() => setSelected(block.id)} className={`group flex items-center gap-2 rounded-xl border bg-white p-3 transition dark:bg-slate-900 ${selected === block.id ? 'border-primary ring-2 ring-primary/10' : 'hover:border-blue-300'} ${block.visible === false ? 'opacity-55' : ''}`}><GripVertical className="h-5 w-5 cursor-grab text-slate-300"/><div className="min-w-0 flex-1"><p className="text-xs font-semibold uppercase tracking-wide text-primary">{block.type.replaceAll('_', ' ')}</p><p className="truncate text-sm font-semibold">{block.settings?.title || block.settings?.text || block.settings?.eyebrow || block.id}</p></div><button type="button" onClick={(event) => { event.stopPropagation(); move(block.id, -1) }} className="rounded p-1.5 hover:bg-slate-100" aria-label="Move up"><ChevronUp className="h-4 w-4"/></button><button type="button" onClick={(event) => { event.stopPropagation(); move(block.id, 1) }} className="rounded p-1.5 hover:bg-slate-100" aria-label="Move down"><ChevronDown className="h-4 w-4"/></button><button type="button" onClick={(event) => { event.stopPropagation(); duplicate(block) }} className="rounded p-1.5 hover:bg-slate-100" aria-label="Duplicate"><Copy className="h-4 w-4"/></button><button type="button" onClick={(event) => { event.stopPropagation(); remove(block.id) }} className="rounded p-1.5 text-red-500 hover:bg-red-50" aria-label="Delete"><Trash2 className="h-4 w-4"/></button></article>{block.type === 'row' && <div className="rounded-lg border border-dashed p-2"><div className="flex flex-wrap gap-1">{blockTypes.filter(([type]) => type !== 'row').map(([type, label]) => <button type="button" key={type} onClick={() => add(type, block.id)} className="rounded bg-blue-50 px-2 py-1 text-[11px] font-semibold text-primary">+ {label}</button>)}</div>{children.length ? <div className="mt-2 space-y-2">{children.map((child) => <TreeNode key={child.id} block={child} depth={depth + 1} selected={selected} setSelected={setSelected} add={add} move={move} duplicate={duplicate} remove={remove} dragId={dragId} drop={drop}/>)}</div> : <p className="py-3 text-center text-xs text-slate-400">Drop or add blocks inside this row.</p>}</div>}</div>
}

export default function MarketplaceBuilderPage() {
  const { can } = useAuth(); const [document, setDocument] = useState(null); const [saved, setSaved] = useState(null); const [catalog, setCatalog] = useState({}); const [media, setMedia] = useState([]); const [versions, setVersions] = useState([]); const [templates, setTemplates] = useState([]); const [templateMeta, setTemplateMeta] = useState({ current_page: 1, last_page: 1, total: 0 }); const [templateSearch, setTemplateSearch] = useState(''); const [templatePreview, setTemplatePreview] = useState(null); const [lockVersion, setLockVersion] = useState(1); const [selected, setSelected] = useState('theme'); const [mode, setMode] = useState('edit'); const [viewport, setViewport] = useState('desktop'); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [versionsOpen, setVersionsOpen] = useState(false); const [templatesOpen, setTemplatesOpen] = useState(false); const [mediaOpen, setMediaOpen] = useState(false); const [history, setHistory] = useState([]); const [future, setFuture] = useState([]); const dragId = useRef(null)
  const loadThemes = (search = templateSearch, page = 1) => getMarketplaceTemplates(search, page).then((result) => { setTemplates(result.data || []); setTemplateMeta(result.meta || { current_page: 1, last_page: 1, total: 0 }) })
  const load = () => { setLoading(true); Promise.all([getMarketplaceBuilder(), getMarketplaceCatalog(), getMarketplaceMedia(), getMarketplaceVersions(), getMarketplaceTemplates()]).then(([builder, catalogResult, mediaResult, versionsResult, templateResult]) => { const doc = normalizeDocument(builder.data.draft_document); setDocument(doc); setSaved(deepClone(doc)); setLockVersion(builder.data.lock_version || 1); setTemplates(templateResult.data || []); setTemplateMeta(templateResult.meta || { current_page: 1, last_page: 1, total: 0 }); setCatalog(catalogResult.data); setMedia(mediaResult.data); setVersions(versionsResult.data) }).catch((requestError) => setError(requestError.message)).finally(() => setLoading(false)) }
  useEffect(load, [])
  const dirty = Boolean(document && saved && JSON.stringify(document) !== JSON.stringify(saved))
  useEffect(() => { if (!dirty) return undefined; const warn = (event) => { event.preventDefault(); event.returnValue = '' }; window.addEventListener('beforeunload', warn); return () => window.removeEventListener('beforeunload', warn) }, [dirty])
  const commit = (next) => { setHistory((items) => [...items.slice(-39), deepClone(document)]); setFuture([]); setDocument(next) }
  const undo = () => { if (!history.length) return; setFuture((items) => [deepClone(document), ...items]); setDocument(history.at(-1)); setHistory((items) => items.slice(0, -1)) }
  const redo = () => { if (!future.length) return; setHistory((items) => [...items, deepClone(document)]); setDocument(future[0]); setFuture((items) => items.slice(1)) }
  const add = (type, parentId = null) => { const block = makeBlock(type); commit({ ...document, sections: parentId ? mapBlocks(document.sections, parentId, (parent) => ({ ...parent, settings: { ...parent.settings, children: [...(parent.settings.children || []), block] } })) : [...document.sections, block] }); setSelected(block.id) }
  const updateBlock = (block) => commit({ ...document, sections: mapBlocks(document.sections, block.id, () => block) })
  const remove = (id) => { commit({ ...document, sections: removeBlock(document.sections, id) }); setSelected('theme') }
  const duplicate = (block) => { const copy = reidentify(block); commit({ ...document, sections: insertBlock(document.sections, block.id, copy, false) }); setSelected(copy.id) }
  const move = (id, direction) => commit({ ...document, sections: moveSibling(document.sections, id, direction) })
  const drop = (targetId, inside) => { const sourceId = dragId.current; if (!sourceId || sourceId === targetId) return; const source = findBlock(document.sections, sourceId); if (!source || findBlock(source.settings?.children || [], targetId)) return; const without = removeBlock(document.sections, sourceId); commit({ ...document, sections: insertBlock(without, targetId, source, inside) }); dragId.current = null }
  const save = async (quiet = false) => { if (!dirty) return; setSaving(true); setError(''); try { const result = await saveMarketplaceDraft(document, lockVersion); setSaved(deepClone(document)); setLockVersion(result.data.lock_version); if (!quiet) await Swal.fire({ icon: 'success', title: 'Draft saved', text: result.message, timer: 1200, showConfirmButton: false }) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  useEffect(() => { if (!dirty || saving || !can('marketplace_builder.update')) return undefined; const timer = setTimeout(async () => { setSaving(true); try { const result = await saveMarketplaceDraft(document, lockVersion); setSaved(deepClone(document)); setLockVersion(result.data.lock_version) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }, 15000); return () => clearTimeout(timer) }, [dirty, document, lockVersion, saving, can])
  const publish = async () => { if (dirty) { setError('Save the draft before publishing.'); return } const confirmation = await Swal.fire({ title: 'Publish marketplace?', html: '<input id="release-name" class="swal2-input" maxlength="120" placeholder="Version name (optional)"><textarea id="release-note" class="swal2-textarea" maxlength="500" placeholder="Release note (optional)"></textarea>', icon: 'question', showCancelButton: true, confirmButtonText: 'Publish', preConfirm: () => ({ name: window.document.getElementById('release-name')?.value || '', release_note: window.document.getElementById('release-note')?.value || '' }) }); if (!confirmation.isConfirmed) return; setSaving(true); try { const result = await publishMarketplace(confirmation.value); clearMarketplaceContentCache(); setVersions((await getMarketplaceVersions()).data); await Swal.fire({ icon: 'success', title: 'Marketplace published', text: result.message }) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const schedule = async () => { if (dirty) { setError('Save the draft before scheduling.'); return } const result = await Swal.fire({ title: 'Schedule publication', html: '<input id="schedule-date" type="datetime-local" class="swal2-input"><input id="schedule-name" class="swal2-input" maxlength="120" placeholder="Version name (optional)"><textarea id="schedule-note" class="swal2-textarea" maxlength="500" placeholder="Release note (optional)"></textarea>', showCancelButton: true, confirmButtonText: 'Schedule', preConfirm: () => { const value = window.document.getElementById('schedule-date')?.value; if (!value) { Swal.showValidationMessage('Choose a future date and time.'); return false } return { scheduled_for: new Date(value).toISOString(), name: window.document.getElementById('schedule-name')?.value || '', release_note: window.document.getElementById('schedule-note')?.value || '' } } }); if (!result.isConfirmed) return; setSaving(true); try { const response = await scheduleMarketplace(result.value); setVersions((await getMarketplaceVersions()).data); await Swal.fire({ icon: 'success', title: 'Publication scheduled', text: response.message }) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const restore = async (version) => { const confirmation = await Swal.fire({ icon: 'warning', title: `Restore version ${version.version_number}?`, text: 'The version will replace your current draft but will not be published.', showCancelButton: true, confirmButtonText: 'Restore draft' }); if (!confirmation.isConfirmed) return; const result = await restoreMarketplaceVersion(version.id); const restored = normalizeDocument(result.data.draft_document); setDocument(restored); setSaved(deepClone(restored)); setLockVersion(result.data.lock_version); setHistory([]); setFuture([]); setVersionsOpen(false) }
  const previewTheme = async (theme) => { setSaving(true); try { const result = await getMarketplaceTemplate(theme.id); setTemplatePreview({ ...theme, document: normalizeDocument(result.data.document) }) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const applyTheme = async (theme) => { const confirmation = await Swal.fire({ icon: 'question', title: `Apply ${theme.name} to draft?`, text: 'Your current draft will be backed up. Live marketplace remains unchanged until Publish.', showCancelButton: true, confirmButtonText: 'Apply to draft' }); if (!confirmation.isConfirmed) return; setSaving(true); setError(''); try { const result = await applyMarketplaceTemplate(theme.id, lockVersion); const next = normalizeDocument(result.data.draft_document); setDocument(next); setSaved(deepClone(next)); setLockVersion(result.data.lock_version); setSelected('theme'); setHistory([]); setFuture([]); setTemplatePreview(null); await loadThemes('', 1); await Swal.fire({ icon: 'success', title: 'Theme applied', text: result.message, timer: 1500, showConfirmButton: false }) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const createTheme = async () => { if (dirty) { setError('Save the draft before creating a reusable theme.'); return } const result = await Swal.fire({ title: 'Create theme from current draft', html: '<input id="theme-name" class="swal2-input" maxlength="120" placeholder="Theme name"><textarea id="theme-description" class="swal2-textarea" maxlength="500" placeholder="Short description"></textarea>', showCancelButton: true, confirmButtonText: 'Create theme', preConfirm: () => { const name = window.document.getElementById('theme-name')?.value.trim(); if (!name) { Swal.showValidationMessage('Theme name is required.'); return false } return { name, description: window.document.getElementById('theme-description')?.value.trim() || '' } } }); if (!result.isConfirmed) return; setSaving(true); try { await createMarketplaceTemplate({ ...result.value, document, design_tokens: document.theme, variants: { header: 'default', hero: document.theme?.preset || 'custom', featured_ad: 'default', category: 'default', product_card: 'default', footer: 'default' } }); await loadThemes('', 1); await Swal.fire({ icon: 'success', title: 'Theme created', timer: 1200, showConfirmButton: false }) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const cloneTheme = async (theme) => { setSaving(true); try { await cloneMarketplaceTemplate(theme.id); await loadThemes(templateSearch, templateMeta.current_page) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const archiveTheme = async (theme) => { const confirmation = await Swal.fire({ icon: 'warning', title: `Archive ${theme.name}?`, showCancelButton: true, confirmButtonText: 'Archive', confirmButtonColor: '#dc2626' }); if (!confirmation.isConfirmed) return; setSaving(true); try { await archiveMarketplaceTemplate(theme.id); await loadThemes(templateSearch, 1) } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  if (loading || !document) return <section><PageHeader eyebrow="Content management" title="Marketplace Builder"/><div className="mt-6 grid gap-4 lg:grid-cols-[220px_1fr_300px]"><Skeleton className="h-[620px]"/><Skeleton className="h-[620px]"/><Skeleton className="h-[620px]"/></div></section>
  const selectedBlock = findBlock(document.sections, selected); const mediaMap = Object.fromEntries(media.map((asset) => [String(asset.id), asset])); const previewWidth = { desktop: 'max-w-[1440px]', tablet: 'max-w-[768px]', mobile: 'max-w-[375px]' }[viewport]
  return <section><PageHeader eyebrow="Content management" title="Marketplace Builder" description="Design, preview, version and publish the complete public marketplace." actions={<><Button variant="secondary" icon={LayoutTemplate} onClick={() => setTemplatesOpen(true)}>Custom Templates</Button><Button variant="secondary" icon={History} onClick={() => setVersionsOpen(true)}>Versions</Button>{can('marketplace_builder.manage_media') && <Button variant="secondary" icon={ImagePlus} onClick={() => setMediaOpen(true)}>Media</Button>}{can('marketplace_builder.update') && <Button icon={Save} loading={saving} disabled={!dirty} onClick={() => save(false)}>Save Draft</Button>}{can('marketplace_builder.publish') && <Button variant="secondary" icon={CalendarClock} disabled={dirty || saving} onClick={schedule}>Schedule</Button>}{can('marketplace_builder.publish') && <Button icon={Send} disabled={dirty || saving} onClick={publish}>Publish</Button>}</>}/>{error && <Alert className="mt-4">{error}<button onClick={() => setError('')} className="ml-2 font-semibold underline">Dismiss</button></Alert>}<div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border bg-white p-2 dark:bg-slate-900"><div className="flex gap-1"><Button size="sm" variant={mode === 'edit' ? 'primary' : 'ghost'} onClick={() => setMode('edit')}>Edit canvas</Button><Button size="sm" variant={mode === 'preview' ? 'primary' : 'ghost'} icon={Eye} onClick={() => setMode('preview')}>Full preview</Button></div><div className="flex items-center gap-1"><Button size="sm" variant="ghost" icon={Undo2} disabled={!history.length} onClick={undo}>Undo</Button><Button size="sm" variant="ghost" icon={Redo2} disabled={!future.length} onClick={redo}>Redo</Button>{dirty ? <Badge tone="warning">Unsaved changes</Badge> : <Badge tone="success">Draft saved</Badge>}</div>{mode === 'preview' && <div className="flex gap-1"><Button size="sm" variant={viewport === 'desktop' ? 'secondary' : 'ghost'} icon={Monitor} onClick={() => setViewport('desktop')}>Desktop</Button><Button size="sm" variant={viewport === 'tablet' ? 'secondary' : 'ghost'} icon={Tablet} onClick={() => setViewport('tablet')}>Tablet</Button><Button size="sm" variant={viewport === 'mobile' ? 'secondary' : 'ghost'} icon={Smartphone} onClick={() => setViewport('mobile')}>Mobile</Button></div>}</div>
    {mode === 'preview' ? <div className="mt-4 overflow-x-auto rounded-xl border bg-slate-200 p-4 dark:bg-slate-950"><div className={`mx-auto transition-all ${previewWidth}`}><MarketplacePreviewShell document={document} media={mediaMap} catalog={catalog}/></div></div> : <div className="mt-4 grid min-h-[720px] gap-4 xl:grid-cols-[220px_minmax(0,1fr)_330px]"><aside className="rounded-xl border bg-white p-3 dark:bg-slate-900"><h2 className="text-sm font-semibold">Block palette</h2><p className="mt-1 text-xs text-slate-500">Add blocks, then drag or use arrow controls to reorder.</p><div className="mt-3 grid grid-cols-2 gap-2 xl:grid-cols-1">{blockTypes.map(([type, label]) => <button type="button" key={type} onClick={() => add(type)} className="flex min-h-10 items-center gap-2 rounded-lg border px-2.5 text-left text-xs font-semibold hover:border-blue-300 hover:bg-blue-50 hover:text-primary"><Plus className="h-3.5 w-3.5"/>{label}</button>)}</div></aside><main className="rounded-xl border bg-slate-100 p-3 dark:bg-slate-950"><div className="mb-3 grid grid-cols-2 gap-2 sm:grid-cols-4">{[['theme', 'Theme'], ['seo', 'SEO'], ['header', 'Header'], ['footer', 'Footer']].map(([key, label]) => <button type="button" key={key} onClick={() => setSelected(key)} className={`h-10 rounded-lg border bg-white text-xs font-semibold dark:bg-slate-900 ${selected === key ? 'border-primary text-primary ring-2 ring-primary/10' : ''}`}>{label}</button>)}</div><div role="tree" aria-label="Marketplace sections" className="space-y-2">{document.sections.map((block) => <TreeNode key={block.id} block={block} depth={0} selected={selected} setSelected={setSelected} add={add} move={move} duplicate={duplicate} remove={remove} dragId={dragId} drop={drop}/>)}</div></main><aside className="rounded-xl border bg-white dark:bg-slate-900"><header className="border-b px-4 py-3"><h2 className="text-sm font-semibold">Properties</h2><p className="mt-0.5 text-xs text-slate-500">Content and safe design settings</p></header><div className="max-h-[760px] overflow-y-auto p-4">{['theme', 'seo', 'header', 'footer'].includes(selected) ? <ShellInspector target={selected} document={document} updateDocument={commit} media={media} onMediaUploaded={(asset) => setMedia((items) => [asset, ...items])} canUploadMedia={can('marketplace_builder.manage_media')}/> : <BlockInspector block={selectedBlock} update={updateBlock} media={media} catalog={catalog}/>}</div></aside></div>}
    <Modal open={versionsOpen} onClose={() => setVersionsOpen(false)} title="Version history" description="Restore a published version into the draft without changing the live page."><div className="space-y-2">{versions.map((version) => <div key={version.id} className="flex items-center gap-3 rounded-xl border p-3"><div className="min-w-0 flex-1"><p className="text-sm font-semibold">Version {version.version_number}{version.name ? ` — ${version.name}` : ''}</p><p className="mt-0.5 text-xs text-slate-500">{new Date(version.published_at).toLocaleString()} · {version.publisher?.name || 'System'}</p>{version.release_note && <p className="mt-2 text-xs text-slate-600">{version.release_note}</p>}</div>{can('marketplace_builder.update') && <Button size="sm" variant="secondary" onClick={() => restore(version)}>Restore</Button>}</div>)}</div></Modal><MediaLibrary open={mediaOpen} onClose={() => setMediaOpen(false)} media={media} setMedia={setMedia}/>
    <Modal open={templatesOpen} onClose={() => setTemplatesOpen(false)} title="Marketplace Themes" description="Preview, apply and manage reusable marketplace designs." size="xl"><ThemeLibrary templates={templates} meta={templateMeta} search={templateSearch} setSearch={setTemplateSearch} load={loadThemes} saving={saving} canManage={can('marketplace_builder.update')} onPreview={previewTheme} onApply={applyTheme} onCreate={createTheme} onClone={cloneTheme} onArchive={archiveTheme}/></Modal>
    <Modal open={Boolean(templatePreview)} onClose={() => setTemplatePreview(null)} title={templatePreview?.name || 'Theme preview'} description="Isolated preview using current marketplace catalog content." size="xl">{templatePreview && <><div className="max-h-[68vh] overflow-auto rounded-xl border bg-slate-100 p-3"><MarketplacePreviewShell document={templatePreview.document} media={mediaMap} catalog={catalog}/></div><div className="mt-4 flex justify-end gap-2"><Button variant="secondary" onClick={() => setTemplatePreview(null)}>Close</Button>{can('marketplace_builder.update') && <Button loading={saving} onClick={() => applyTheme(templatePreview)}>Apply to Draft</Button>}</div></>}</Modal>
  </section>
}

function ThemeLibrary({ templates, meta, search, setSearch, load, saving, canManage, onPreview, onApply, onCreate, onClone, onArchive }) {
  return <section><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-primary">Theme Library</p><h2 className="mt-1 text-lg font-bold">Reusable marketplace themes</h2><p className="mt-1 text-xs text-slate-500">{meta.total || 0} themes · applying a theme creates a safe draft backup.</p></div>{canManage && <Button icon={Plus} loading={saving} onClick={onCreate}>Create from Current Draft</Button>}</div><form onSubmit={(event) => { event.preventDefault(); load(search, 1) }} className="mt-4 flex gap-2"><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search themes..." className="h-10 min-w-0 flex-1 rounded-lg border px-3 text-sm"/><Button variant="secondary">Search</Button></form><div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{templates.map((theme) => { const tokens = theme.design_tokens || {}; return <Card key={theme.id} className="overflow-hidden"><button type="button" onClick={() => onPreview(theme)} className="block w-full text-left"><div className="relative h-32 overflow-hidden" style={{ background: theme.thumbnail_url ? `url(${theme.thumbnail_url}) center/cover` : `linear-gradient(135deg, ${tokens.primary || '#3157E8'}, ${tokens.secondary || '#0891B2'})` }}><div className="absolute inset-x-4 bottom-4 grid grid-cols-3 gap-2"><span className="h-10 rounded-lg bg-white/90 shadow"/><span className="h-10 rounded-lg bg-white/65 shadow"/><span className="h-10 rounded-lg bg-white/40 shadow"/></div><div className="absolute left-3 top-3 flex gap-1.5">{theme.is_active && <Badge tone="success">Live</Badge>}{theme.is_draft && <Badge tone="warning">Draft</Badge>}</div></div><div className="p-4"><h3 className="text-sm font-bold">{theme.name}</h3><p className="mt-1 line-clamp-2 min-h-10 text-xs leading-5 text-slate-500">{theme.description || 'Reusable marketplace design.'}</p><p className="mt-2 text-[11px] text-slate-400">{theme.section_count} sections · Updated {theme.updated_at ? new Date(theme.updated_at).toLocaleDateString() : 'recently'}</p></div></button><div className="flex flex-wrap gap-2 border-t p-3"><Button size="sm" variant="secondary" icon={Eye} onClick={() => onPreview(theme)}>Preview</Button>{canManage && <Button size="sm" onClick={() => onApply(theme)} disabled={theme.is_draft}>Apply</Button>}{canManage && <Button size="sm" variant="ghost" icon={Copy} onClick={() => onClone(theme)}>Clone</Button>}{canManage && <Button size="sm" variant="ghost" icon={Archive} onClick={() => onArchive(theme)} disabled={theme.is_active || theme.is_draft}>Archive</Button>}</div></Card> })}{!templates.length && <div className="col-span-full rounded-xl border border-dashed p-10 text-center text-sm text-slate-500">No themes match your search.</div>}</div>{meta.last_page > 1 && <div className="mt-4 flex justify-center gap-2"><Button size="sm" variant="secondary" disabled={meta.current_page <= 1} onClick={() => load(search, meta.current_page - 1)}>Previous</Button><span className="self-center text-xs text-slate-500">Page {meta.current_page} of {meta.last_page}</span><Button size="sm" variant="secondary" disabled={meta.current_page >= meta.last_page} onClick={() => load(search, meta.current_page + 1)}>Next</Button></div>}</section>
}

function MediaLibrary({ open, onClose, media, setMedia }) {
  const [file, setFile] = useState(null); const [alt, setAlt] = useState(''); const [search, setSearch] = useState(''); const [editing, setEditing] = useState(null); const [saving, setSaving] = useState(false); const [error, setError] = useState('')
  const visible = useMemo(() => media.filter((asset) => `${asset.original_name} ${asset.alt_text}`.toLowerCase().includes(search.toLowerCase())), [media, search])
  const upload = async (event) => { event.preventDefault(); const data = new FormData(); data.append('file', file); data.append('alt_text', alt); setSaving(true); setError(''); try { const result = await uploadMarketplaceMedia(data); setMedia((items) => [result.data, ...items]); setFile(null); setAlt('') } catch (requestError) { setError(requestError.message) } finally { setSaving(false) } }
  const archive = async (asset) => { const confirmation = await Swal.fire({ icon: 'warning', title: 'Archive image?', text: asset.original_name, showCancelButton: true, confirmButtonText: 'Archive' }); if (!confirmation.isConfirmed) return; try { await archiveMarketplaceMedia(asset.id); setMedia((items) => items.filter((item) => item.id !== asset.id)) } catch (requestError) { setError(requestError.message) } }
  const saveAlt = async (asset) => { if (!editing?.value.trim()) return; try { const result = await updateMarketplaceMedia(asset.id, editing.value.trim()); setMedia((items) => items.map((item) => item.id === asset.id ? result.data : item)); setEditing(null) } catch (requestError) { setError(requestError.message) } }
  return <Modal open={open} onClose={onClose} title="Marketplace media" description="Search, upload and maintain accessible marketplace images." size="xl"><form onSubmit={upload} className="grid gap-3 rounded-xl border bg-slate-50 p-4 sm:grid-cols-[1fr_1fr_auto]"><input required type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setFile(event.target.files?.[0] || null)} className="rounded-lg border bg-white p-2 text-xs"/><input required value={alt} onChange={(event) => setAlt(event.target.value)} placeholder="Accessible image description" className="rounded-lg border px-3 text-xs"/><Button loading={saving} disabled={!file || !alt.trim()} icon={ImagePlus}>Upload</Button></form>{error && <Alert className="mt-3">{error}</Alert>}<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search media by filename or description" className="mt-4 h-10 w-full rounded-lg border px-3 text-sm"/><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{visible.map((asset) => <Card key={asset.id} className="overflow-hidden"><img loading="lazy" src={asset.url} alt={asset.alt_text} className="h-36 w-full bg-slate-50 object-contain"/><div className="p-3"><p className="truncate text-xs font-semibold">{asset.original_name}</p>{editing?.id === asset.id ? <div className="mt-2"><textarea autoFocus rows="2" value={editing.value} onChange={(event) => setEditing({ id: asset.id, value: event.target.value })} className="w-full rounded-lg border p-2 text-xs"/><div className="mt-2 flex gap-2"><button type="button" onClick={() => saveAlt(asset)} className="text-xs font-semibold text-primary">Save</button><button type="button" onClick={() => setEditing(null)} className="text-xs text-slate-500">Cancel</button></div></div> : <p className="mt-1 line-clamp-2 text-xs text-slate-500">{asset.alt_text}</p>}<p className="mt-1 text-[11px] text-slate-400">{asset.width}×{asset.height} · {(asset.size / 1024).toFixed(0)} KB</p><div className="mt-3 flex justify-between"><button type="button" onClick={() => setEditing({ id: asset.id, value: asset.alt_text })} className="text-xs font-semibold text-primary">Edit alt text</button><button type="button" onClick={() => archive(asset)} className="inline-flex items-center gap-1 text-xs font-semibold text-red-600"><Archive className="h-3.5 w-3.5"/>Archive</button></div></div></Card>)}</div>{!visible.length && <EmptyState title="No media found" description="Change your search or upload a new image."/>}</Modal>
}
